UPDATE OR INSERT INTO FPC_MESSAGES (CODE, SEVERITY, MESSAGE_PATTERN, DESCRIPTION_PTBR, PROBABLE_CAUSE, MANUAL_SOLUTION, CAN_AUTO_FIX, AUTO_FIX_STRATEGY) VALUES (1009, 'FATAL', 'Memória insuficiente', 'The compiler doesn''t have enough memory to compile your program. There are
several remedies for this:

• If you''re using the build option of the compiler, try compiling the
different units manually.
• If you''re compiling a huge program, split it up into units, and compile
these separately.
• If the previous two don''t work, recompile the compiler with a bigger
heap. (You can use the ''-Ch'' option for this, Ch.)', 'Erro crítico do compilador, ausência de arquivos essenciais, memória esgotada ou parâmetros inválidos.', 'Verifique a integridade da instalação do FPC, opções de projeto e recursos disponíveis do sistema.', 'N', '') MATCHING (CODE);
UPDATE OR INSERT INTO FPC_MESSAGES (CODE, SEVERITY, MESSAGE_PATTERN, DESCRIPTION_PTBR, PROBABLE_CAUSE, MANUAL_SOLUTION, CAN_AUTO_FIX, AUTO_FIX_STRATEGY) VALUES (1011, 'ERROR', 'Gravando arquivo Tabela Recursos ''String'': $1', 'This message is shown when the compiler encounters an error when writing
the Resource String Table file.', 'Erro sintático ou semântico que viola a especificação da linguagem Object Pascal / Free Pascal.', 'Ajuste o código conforme a sintaxe esperada e certifique-se de que todos os tipos e símbolos existem.', 'N', '') MATCHING (CODE);
UPDATE OR INSERT INTO FPC_MESSAGES (CODE, SEVERITY, MESSAGE_PATTERN, DESCRIPTION_PTBR, PROBABLE_CAUSE, MANUAL_SOLUTION, CAN_AUTO_FIX, AUTO_FIX_STRATEGY) VALUES (1017, 'ERROR', 'Caminho "$1" não existe', 'The specified path does not exist.', 'Erro sintático ou semântico que viola a especificação da linguagem Object Pascal / Free Pascal.', 'Ajuste o código conforme a sintaxe esperada e certifique-se de que todos os tipos e símbolos existem.', 'N', '') MATCHING (CODE);
