UPDATE OR INSERT INTO FPC_MESSAGES (CODE, SEVERITY, MESSAGE_PATTERN, DESCRIPTION_PTBR, PROBABLE_CAUSE, MANUAL_SOLUTION, CAN_AUTO_FIX, AUTO_FIX_STRATEGY) VALUES (1025, 'FATAL', 'Erro do sistema operacional: $1', 'During compilation an operanting system error happened which allows no further compilation.

This section lists the messages that the scanner emits. The scanner takes
care of the lexical structure of the pascal file, i.e. it tries to find
reserved words, strings, etc. It also takes care of directives and
conditional compilation handling.', 'Erro crítico do compilador, ausência de arquivos essenciais, memória esgotada ou parâmetros inválidos.', 'Verifique a integridade da instalação do FPC, opções de projeto e recursos disponíveis do sistema.', 'N', '') MATCHING (CODE);
UPDATE OR INSERT INTO FPC_MESSAGES (CODE, SEVERITY, MESSAGE_PATTERN, DESCRIPTION_PTBR, PROBABLE_CAUSE, MANUAL_SOLUTION, CAN_AUTO_FIX, AUTO_FIX_STRATEGY) VALUES (1026, 'ERROR', 'Compilation raised exception internally', 'Compilation was aborted, due to an exception generation.', 'Erro sintático ou semântico que viola a especificação da linguagem Object Pascal / Free Pascal.', 'Ajuste o código conforme a sintaxe esperada e certifique-se de que todos os tipos e símbolos existem.', 'N', '') MATCHING (CODE);
UPDATE OR INSERT INTO FPC_MESSAGES (CODE, SEVERITY, MESSAGE_PATTERN, DESCRIPTION_PTBR, PROBABLE_CAUSE, MANUAL_SOLUTION, CAN_AUTO_FIX, AUTO_FIX_STRATEGY) VALUES (2000, 'FATAL', 'Fim de arquivo inesperado', 'This typically happens in one of the following cases:

• The source file ends before the final ''end.'' statement. This
happens mostly when the ''begin'' and ''end'' statements aren''t
balanced;
• An include file ends in the middle of a statement.
• A comment was not closed.', 'Erro crítico do compilador, ausência de arquivos essenciais, memória esgotada ou parâmetros inválidos.', 'Verifique a integridade da instalação do FPC, opções de projeto e recursos disponíveis do sistema.', 'N', '') MATCHING (CODE);
