UPDATE OR INSERT INTO FPC_MESSAGES (CODE, SEVERITY, MESSAGE_PATTERN, DESCRIPTION_PTBR, PROBABLE_CAUSE, MANUAL_SOLUTION, CAN_AUTO_FIX, AUTO_FIX_STRATEGY) VALUES (3250, 'NOTE', 'Método virtual "$1" tem baixa visibilidade ($2) que a classe pai $3 ($4)', 'The virtual method overrides an method that is declared with a higher visibility. This might give
unexpected results. In case the new visibility is private than it might be that a call to inherited in a
new child class will call the higher visible method in a parent class and ignores the private method.', 'Informação do compilador sobre decisões de código gerado, inlining ou conversões implícitas.', 'Avalie se o comportamento atende aos requisitos de performance e arquitetura do projeto.', 'N', '') MATCHING (CODE);
UPDATE OR INSERT INTO FPC_MESSAGES (CODE, SEVERITY, MESSAGE_PATTERN, DESCRIPTION_PTBR, PROBABLE_CAUSE, MANUAL_SOLUTION, CAN_AUTO_FIX, AUTO_FIX_STRATEGY) VALUES (3251, 'ERROR', 'Campos não podem aparecer depois dem um método ou definição propriedade, inicie uma nova seção de visibilidade primeiro', 'Once a method or property has been defined in a class or object, you cannot define any fields afterwards
without starting a new visibility section (such as ''public'', ''private'', etc.). The reason is
that otherwise the source code can appear ambiguous to the compiler, since it is possible to use modifiers
such as ''default'' and ''register'' also as field names.', 'Erro sintático ou semântico que viola a especificação da linguagem Object Pascal / Free Pascal.', 'Ajuste o código conforme a sintaxe esperada e certifique-se de que todos os tipos e símbolos existem.', 'N', '') MATCHING (CODE);
UPDATE OR INSERT INTO FPC_MESSAGES (CODE, SEVERITY, MESSAGE_PATTERN, DESCRIPTION_PTBR, PROBABLE_CAUSE, MANUAL_SOLUTION, CAN_AUTO_FIX, AUTO_FIX_STRATEGY) VALUES (3252, 'ERROR', 'Parâmetros ou tipos resultado não podem conter definições locais de tipo. Use uma definição de tipo separada em um bloco de tipos', 'In Pascal, types are not considered to be identical simply because they are semantically equivalent.
Two variables or parameters are only considered to be of the same type if they refer to the
same type definition.
As a result, it is not allowed to define new types inside parameter lists, because then it is impossible to
refer to the same type definition in the procedure headers of the interface and implementation of a unit
(both procedure headers would define a separate type). Keep in mind that expressions such as
``file of byte'''' or ``string[50]'''' also define a new type.', 'Erro sintático ou semântico que viola a especificação da linguagem Object Pascal / Free Pascal.', 'Ajuste o código conforme a sintaxe esperada e certifique-se de que todos os tipos e símbolos existem.', 'N', '') MATCHING (CODE);
UPDATE OR INSERT INTO FPC_MESSAGES (CODE, SEVERITY, MESSAGE_PATTERN, DESCRIPTION_PTBR, PROBABLE_CAUSE, MANUAL_SOLUTION, CAN_AUTO_FIX, AUTO_FIX_STRATEGY) VALUES (3253, 'ERROR', 'Conflito ABSTRACT e SEALED', 'ABSTRACT and SEALED cannot be used together in one declaration', 'Erro sintático ou semântico que viola a especificação da linguagem Object Pascal / Free Pascal.', 'Ajuste o código conforme a sintaxe esperada e certifique-se de que todos os tipos e símbolos existem.', 'N', '') MATCHING (CODE);
