UPDATE OR INSERT INTO FPC_MESSAGES (CODE, SEVERITY, MESSAGE_PATTERN, DESCRIPTION_PTBR, PROBABLE_CAUSE, MANUAL_SOLUTION, CAN_AUTO_FIX, AUTO_FIX_STRATEGY) VALUES (3266, 'ERROR', 'Mensagens Objective-C requerem que seu nome seletor Objective-C seja especificado usando a diretiva "message".', 'Objective-C messages require their Objective-C name (selector name) to be specified using the ''message `someName:'''' procedure directive.
While bindings to other languages automatically generate such names based on the identifier you use (by replacing
all underscores with colons), this is unsafe since nothing prevents an Objective-C method name to contain actual
colons.', 'Erro sintático ou semântico que viola a especificação da linguagem Object Pascal / Free Pascal.', 'Ajuste o código conforme a sintaxe esperada e certifique-se de que todos os tipos e símbolos existem.', 'N', '') MATCHING (CODE);
UPDATE OR INSERT INTO FPC_MESSAGES (CODE, SEVERITY, MESSAGE_PATTERN, DESCRIPTION_PTBR, PROBABLE_CAUSE, MANUAL_SOLUTION, CAN_AUTO_FIX, AUTO_FIX_STRATEGY) VALUES (3267, 'ERROR', 'Objective-C não tem construtores nem destruidores formais. Use as mensagens ''alloc'', ''initXXX'' e ''dealloc''.', 'The Objective-C language does not have any constructors or destructors. While there are some messages with a similar
purpose (such as ''init'' and ''dealloc''), these cannot be identified using automatic parsers and do not
guarantee anything like Pascal constructors/destructors (e.g., you have to take care of only calling ``designated''''
inherited ``constructors''''). For these reasons, we have opted to follow the standard Objective-C patterns for
instance creation/destruction.', 'Erro sintático ou semântico que viola a especificação da linguagem Object Pascal / Free Pascal.', 'Ajuste o código conforme a sintaxe esperada e certifique-se de que todos os tipos e símbolos existem.', 'N', '') MATCHING (CODE);
UPDATE OR INSERT INTO FPC_MESSAGES (CODE, SEVERITY, MESSAGE_PATTERN, DESCRIPTION_PTBR, PROBABLE_CAUSE, MANUAL_SOLUTION, CAN_AUTO_FIX, AUTO_FIX_STRATEGY) VALUES (3268, 'ERROR', 'Nome mensagem é muito longo (max. 255 caracteres)', 'Due to compiler implementation reasons, message names are currently limited to 255 characters.', 'Erro sintático ou semântico que viola a especificação da linguagem Object Pascal / Free Pascal.', 'Ajuste o código conforme a sintaxe esperada e certifique-se de que todos os tipos e símbolos existem.', 'N', '') MATCHING (CODE);
UPDATE OR INSERT INTO FPC_MESSAGES (CODE, SEVERITY, MESSAGE_PATTERN, DESCRIPTION_PTBR, PROBABLE_CAUSE, MANUAL_SOLUTION, CAN_AUTO_FIX, AUTO_FIX_STRATEGY) VALUES (3269, 'ERROR', 'Nome símbolo mensagem Objective-C para "$1" é muito longo', 'Due to compiler implementation reasons, mangled message names (i.e., the symbol names used in the assembler
code) are currently limited to 255 characters.', 'Erro sintático ou semântico que viola a especificação da linguagem Object Pascal / Free Pascal.', 'Ajuste o código conforme a sintaxe esperada e certifique-se de que todos os tipos e símbolos existem.', 'N', '') MATCHING (CODE);
UPDATE OR INSERT INTO FPC_MESSAGES (CODE, SEVERITY, MESSAGE_PATTERN, DESCRIPTION_PTBR, PROBABLE_CAUSE, MANUAL_SOLUTION, CAN_AUTO_FIX, AUTO_FIX_STRATEGY) VALUES (3270, 'HINT', 'Definindo uma nova classe raiz Objective-C. Para derivar de outra classe raiz (ex., NSObject), especifique-a como pai da classe', 'If no parent class is specified for an Object Pascal class, then it automatically derives from TObject.
Objective-C classes however do not automatically derive from NSObject, because one can have multiple
root classes in Objective-C. For example, in the Cocoa framework both NSObject and NSProxy are root classes.
Therefore, you have to explicitly define a parent class (such as NSObject) if you want to derive your
Objective-C class from it.', 'O compilador detectou código redundante, parâmetros não utilizados ou oportunidades de otimização.', 'Revise a necessidade do elemento ou use supressão local se o padrão for intencional.', 'N', '') MATCHING (CODE);
UPDATE OR INSERT INTO FPC_MESSAGES (CODE, SEVERITY, MESSAGE_PATTERN, DESCRIPTION_PTBR, PROBABLE_CAUSE, MANUAL_SOLUTION, CAN_AUTO_FIX, AUTO_FIX_STRATEGY) VALUES (3271, 'ERROR', 'Classes Objective-C não podem ter seções PUBLISHED', 'In Object Pascal, ``published'''' determines whether or not RTTI is generated. Since the Objective-C runtime always needs
RTTI for everything, this specified does not make sense for Objective-C classes.', 'Erro sintático ou semântico que viola a especificação da linguagem Object Pascal / Free Pascal.', 'Ajuste o código conforme a sintaxe esperada e certifique-se de que todos os tipos e símbolos existem.', 'N', '') MATCHING (CODE);
UPDATE OR INSERT INTO FPC_MESSAGES (CODE, SEVERITY, MESSAGE_PATTERN, DESCRIPTION_PTBR, PROBABLE_CAUSE, MANUAL_SOLUTION, CAN_AUTO_FIX, AUTO_FIX_STRATEGY) VALUES (3272, 'FATAL', 'Este módulo requer que seja especificado uma chave de modo Objective-C para ser compilado', 'This error indicates the use of Objective-C language features without an Objective-C mode switch
active. Enable one via the -M command line switch, or the {\$modeswitch x} directive.', 'Erro crítico do compilador, ausência de arquivos essenciais, memória esgotada ou parâmetros inválidos.', 'Verifique a integridade da instalação do FPC, opções de projeto e recursos disponíveis do sistema.', 'N', '') MATCHING (CODE);
UPDATE OR INSERT INTO FPC_MESSAGES (CODE, SEVERITY, MESSAGE_PATTERN, DESCRIPTION_PTBR, PROBABLE_CAUSE, MANUAL_SOLUTION, CAN_AUTO_FIX, AUTO_FIX_STRATEGY) VALUES (3273, 'ERROR', 'Inherited methods can only be overridden in Objective-C and Java, add "override" (inherited method defined in $1)', 'Diagnóstico ERROR código 3273 emitido pelo compilador Free Pascal: Inherited methods can only be overridden in Objective-C and Java, add "override" (inherited method defined in $1)', 'Erro sintático ou semântico que viola a especificação da linguagem Object Pascal / Free Pascal.', 'Ajuste o código conforme a sintaxe esperada e certifique-se de que todos os tipos e símbolos existem.', 'N', '') MATCHING (CODE);
UPDATE OR INSERT INTO FPC_MESSAGES (CODE, SEVERITY, MESSAGE_PATTERN, DESCRIPTION_PTBR, PROBABLE_CAUSE, MANUAL_SOLUTION, CAN_AUTO_FIX, AUTO_FIX_STRATEGY) VALUES (3274, 'HINT', 'Inherited methods can only be overridden in Objective-C and Java, add "override" (inherited method defined in $1).', 'It is not possible to ''reintroduce'' methods in Objective-C or Java like in Object Pascal. Methods with the same
name always map to the same virtual method entry. In order to make this clear in the source code,
the compiler always requires the ''override'' directive to be specified when implementing overriding
Objective-C or Java methods in Pascal. If the implementation is external, this rule is relaxed because Objective-C and Java
do not have any ''override''-style keyword (since it''s the default and only behaviour in these languages),
which makes it hard for automated header conversion tools to include it everywhere.
The type in which the inherited method is defined is explicitly mentioned, because this may either
be an objcclass or an objccategory in case of Objective-C.', 'O compilador detectou código redundante, parâmetros não utilizados ou oportunidades de otimização.', 'Revise a necessidade do elemento ou use supressão local se o padrão for intencional.', 'N', '') MATCHING (CODE);
UPDATE OR INSERT INTO FPC_MESSAGES (CODE, SEVERITY, MESSAGE_PATTERN, DESCRIPTION_PTBR, PROBABLE_CAUSE, MANUAL_SOLUTION, CAN_AUTO_FIX, AUTO_FIX_STRATEGY) VALUES (3275, 'ERROR', 'Nome mensagem "$1" na classe herdada é diferente do nome mensagem "$2" na classe atual.', 'An overriding Objective-C method cannot have a different message name than an inherited method. The reason
is that these message names uniquely define the message to the Objective-C runtime, which means that
giving them a different message name breaks the ``override'''' semantics.', 'Erro sintático ou semântico que viola a especificação da linguagem Object Pascal / Free Pascal.', 'Ajuste o código conforme a sintaxe esperada e certifique-se de que todos os tipos e símbolos existem.', 'N', '') MATCHING (CODE);
UPDATE OR INSERT INTO FPC_MESSAGES (CODE, SEVERITY, MESSAGE_PATTERN, DESCRIPTION_PTBR, PROBABLE_CAUSE, MANUAL_SOLUTION, CAN_AUTO_FIX, AUTO_FIX_STRATEGY) VALUES (3276, 'ERROR', 'It is not yet possible to make unique copies of Objective-C or Java types', 'Duplicating an Objective-C or Java type using ''type x = type y;'' is not yet supported. You may be able to
obtain the desired effect using ''type x = objcclass(y) end;'' resp.{} ''type x = class(y) end;'' instead.', 'Erro sintático ou semântico que viola a especificação da linguagem Object Pascal / Free Pascal.', 'Ajuste o código conforme a sintaxe esperada e certifique-se de que todos os tipos e símbolos existem.', 'N', '') MATCHING (CODE);
UPDATE OR INSERT INTO FPC_MESSAGES (CODE, SEVERITY, MESSAGE_PATTERN, DESCRIPTION_PTBR, PROBABLE_CAUSE, MANUAL_SOLUTION, CAN_AUTO_FIX, AUTO_FIX_STRATEGY) VALUES (3277, 'ERROR', 'Categorias Objective-C e classes auxiliares Object Pascal não podem ser usadas como tipos', 'It is not possible to declare a variable as an instance of an Objective-C
category or an Object Pascal class helper. A category/class helper adds
methods to the scope of an existing class, but does not define a type by
itself. An exception of this rule is when inheriting an Object Pascal class
helper from another class helper.', 'Erro sintático ou semântico que viola a especificação da linguagem Object Pascal / Free Pascal.', 'Ajuste o código conforme a sintaxe esperada e certifique-se de que todos os tipos e símbolos existem.', 'N', '') MATCHING (CODE);
UPDATE OR INSERT INTO FPC_MESSAGES (CODE, SEVERITY, MESSAGE_PATTERN, DESCRIPTION_PTBR, PROBABLE_CAUSE, MANUAL_SOLUTION, CAN_AUTO_FIX, AUTO_FIX_STRATEGY) VALUES (3278, 'ERROR', 'Categorias não sobrepõem, mas substituem métodos. Use "REINTRODUCE".', 'Diagnóstico ERROR código 3278 emitido pelo compilador Free Pascal: Categorias não sobrepõem, mas substituem métodos. Use "REINTRODUCE".', 'Erro sintático ou semântico que viola a especificação da linguagem Object Pascal / Free Pascal.', 'Ajuste o código conforme a sintaxe esperada e certifique-se de que todos os tipos e símbolos existem.', 'N', '') MATCHING (CODE);
UPDATE OR INSERT INTO FPC_MESSAGES (CODE, SEVERITY, MESSAGE_PATTERN, DESCRIPTION_PTBR, PROBABLE_CAUSE, MANUAL_SOLUTION, CAN_AUTO_FIX, AUTO_FIX_STRATEGY) VALUES (3279, 'ERROR', 'Métodos substituídos podem apenas ser reintroduzidos em Objective-C, adicione "REINTRODUCE" (método substituído definido em $1).', 'Diagnóstico ERROR código 3279 emitido pelo compilador Free Pascal: Métodos substituídos podem apenas ser reintroduzidos em Objective-C, adicione "REINTRODUCE" (método substituído definido em $1).', 'Erro sintático ou semântico que viola a especificação da linguagem Object Pascal / Free Pascal.', 'Ajuste o código conforme a sintaxe esperada e certifique-se de que todos os tipos e símbolos existem.', 'N', '') MATCHING (CODE);
UPDATE OR INSERT INTO FPC_MESSAGES (CODE, SEVERITY, MESSAGE_PATTERN, DESCRIPTION_PTBR, PROBABLE_CAUSE, MANUAL_SOLUTION, CAN_AUTO_FIX, AUTO_FIX_STRATEGY) VALUES (3280, 'HINT', 'Métodos substituídos podem apenas ser reintroduzidos em Objective-C, adicione "REINTRODUCE" (método substituído definido em $1).', 'A category replaces an existing method in an Objective-C class, rather than that it overrides it.
Calling an inherited method from an category method will call that method in
the extended class'' parent, not in the extended class itself. The
replaced method in the original class is basically lost, and can no longer be
called or referred to. This behaviour corresponds somewhat more closely to
''reintroduce'' than to ''override'' (although in case of ''reintroduce''
in Object Pascal, hidden methods are still reachable via inherited).
The type in which the inherited method is defined is explicitly mentioned, because this may either
be an objcclass or an objccategory.', 'O compilador detectou código redundante, parâmetros não utilizados ou oportunidades de otimização.', 'Revise a necessidade do elemento ou use supressão local se o padrão for intencional.', 'N', '') MATCHING (CODE);
UPDATE OR INSERT INTO FPC_MESSAGES (CODE, SEVERITY, MESSAGE_PATTERN, DESCRIPTION_PTBR, PROBABLE_CAUSE, MANUAL_SOLUTION, CAN_AUTO_FIX, AUTO_FIX_STRATEGY) VALUES (3281, 'ERROR', '''Getter'' para implementação interface deve usar a convenção de chamada padrão do alvo.', 'Interface getters are called via a helper in the run time library, and hence
