UPDATE OR INSERT INTO FPC_MESSAGES (CODE, SEVERITY, MESSAGE_PATTERN, DESCRIPTION_PTBR, PROBABLE_CAUSE, MANUAL_SOLUTION, CAN_AUTO_FIX, AUTO_FIX_STRATEGY) VALUES (3293, 'ERROR', 'Constantes caracteres/unicode não podem ser convertidas em "ansi/shortstring" em tempo de compilação', 'It is not possible to use unicodechar and unicodestring constants in
constant expressions that have to be converted into an ansistring or shortstring
at compile time, for example inside typed constants. The reason is that the
compiler cannot know what the actual ansi encoding will be at run time.', 'Erro sintático ou semântico que viola a especificação da linguagem Object Pascal / Free Pascal.', 'Ajuste o código conforme a sintaxe esperada e certifique-se de que todos os tipos e símbolos existem.', 'N', '') MATCHING (CODE);
UPDATE OR INSERT INTO FPC_MESSAGES (CODE, SEVERITY, MESSAGE_PATTERN, DESCRIPTION_PTBR, PROBABLE_CAUSE, MANUAL_SOLUTION, CAN_AUTO_FIX, AUTO_FIX_STRATEGY) VALUES (3294, 'ERROR', 'Laços "For-in Objective-Pascal" requerem que a chave \{\$modeswitch ObjectiveC2\} esteja ativa', 'Objective-C ``fast enumeration'''' support was added in Objective-C 2.0, and
hence the appropriate modeswitch has to be activated to expose this feature.
Note that Objective-C 2.0 programs require Mac OS X 10.5 or later.', 'Erro sintático ou semântico que viola a especificação da linguagem Object Pascal / Free Pascal.', 'Ajuste o código conforme a sintaxe esperada e certifique-se de que todos os tipos e símbolos existem.', 'N', '') MATCHING (CODE);
UPDATE OR INSERT INTO FPC_MESSAGES (CODE, SEVERITY, MESSAGE_PATTERN, DESCRIPTION_PTBR, PROBABLE_CAUSE, MANUAL_SOLUTION, CAN_AUTO_FIX, AUTO_FIX_STRATEGY) VALUES (3295, 'ERROR', 'O compilador não encontrou os tipos "NSFastEnumerationProtocol" ou "NSFastEnumerationState" na unidade "CocoaAll"', 'Objective-C for-in loops (fast enumeration) require that the compiler can
find a unit called CocoaAll that contains definitions for the
NSFastEnumerationProtocol and NSFastEnumerationState types. If you get this
error, most likely the compiler is finding and loading an alternate CocoaAll
unit.', 'Erro sintático ou semântico que viola a especificação da linguagem Object Pascal / Free Pascal.', 'Ajuste o código conforme a sintaxe esperada e certifique-se de que todos os tipos e símbolos existem.', 'N', '') MATCHING (CODE);
UPDATE OR INSERT INTO FPC_MESSAGES (CODE, SEVERITY, MESSAGE_PATTERN, DESCRIPTION_PTBR, PROBABLE_CAUSE, MANUAL_SOLUTION, CAN_AUTO_FIX, AUTO_FIX_STRATEGY) VALUES (3296, 'ERROR', 'Constantes tipadas do tipo ''procedimento é aninhado'' só podem ser inicializadas com NIL e procedimentos/funções globais', 'A nested procedural variable consists of two components: the address of the
procedure/function to call (which is always known at compile time), and also
a parent frame pointer (which is never known at compile time) in case the
procedural variable contains a reference to a nested procedure/function.
Therefore such typed constants can only be initialized with global
functions/procedures since these do not require a parent frame pointer.', 'Erro sintático ou semântico que viola a especificação da linguagem Object Pascal / Free Pascal.', 'Ajuste o código conforme a sintaxe esperada e certifique-se de que todos os tipos e símbolos existem.', 'N', '') MATCHING (CODE);
UPDATE OR INSERT INTO FPC_MESSAGES (CODE, SEVERITY, MESSAGE_PATTERN, DESCRIPTION_PTBR, PROBABLE_CAUSE, MANUAL_SOLUTION, CAN_AUTO_FIX, AUTO_FIX_STRATEGY) VALUES (3297, 'FATAL', 'Declaração de classe genérica dentro de outra classe genérica não é permitido', 'At the moment, scanner supports recording of only one token buffer at the time
(guarded by internal error 200511173 in tscannerfile.startrecordtokens).
Since generics are implemented by recording tokens, it is not possible to
have declaration of generic class inside another generic class.', 'Erro crítico do compilador, ausência de arquivos essenciais, memória esgotada ou parâmetros inválidos.', 'Verifique a integridade da instalação do FPC, opções de projeto e recursos disponíveis do sistema.', 'N', '') MATCHING (CODE);
UPDATE OR INSERT INTO FPC_MESSAGES (CODE, SEVERITY, MESSAGE_PATTERN, DESCRIPTION_PTBR, PROBABLE_CAUSE, MANUAL_SOLUTION, CAN_AUTO_FIX, AUTO_FIX_STRATEGY) VALUES (3298, 'ERROR', 'Forward declaration "$1" must be resolved before a class can conform to or implement it', 'An Objective-C protocol or Java Interface must be fully defined before classes can conform to it.
This error occurs in the following situation (example for Objective-C, but the same goes for Java interfaces):

Type MyProtocol = objcprotoocl;
ChildClass = Class(NSObject,MyProtocol)
...
end;

