UPDATE OR INSERT INTO FPC_MESSAGES (CODE, SEVERITY, MESSAGE_PATTERN, DESCRIPTION_PTBR, PROBABLE_CAUSE, MANUAL_SOLUTION, CAN_AUTO_FIX, AUTO_FIX_STRATEGY) VALUES (3326, 'WARNING', 'Automatically generated property getter/setter $1 overrides the same-named getter/setter in class $2', 'Automatically generated property getters/setters on the JVM platform are virtual methods, because
the JVM does not support non-virtual methods that can be changed in child classes. This means
that if a child class changes an inherited property definition, the behaviour of that property
can change compared to native targets since even if a variable is declared as the parent type,
by calling the virtual method the getter from the child will be used. This is different from
the behaviour on native targets or when not activating automatically generated setters/getters,
because in that case only the declared type of a variable influences the property behaviour.', 'Possível falha de lógica, incompatibilidade de tipos, obsolescência ou efeitos colaterais em tempo de execução.', 'Corrija a inconsistência apontada para evitar comportamentos inesperados no executável final.', 'N', '') MATCHING (CODE);
