UPDATE OR INSERT INTO FPC_MESSAGES (CODE, SEVERITY, MESSAGE_PATTERN, DESCRIPTION_PTBR, PROBABLE_CAUSE, MANUAL_SOLUTION, CAN_AUTO_FIX, AUTO_FIX_STRATEGY) VALUES (3348, 'ERROR', 'Thread variables inside classes or records must be class variables', 'A ''threadvar'' section inside a class or record was started without it being prefixed by ''class''.', 'Erro sintático ou semântico que viola a especificação da linguagem Object Pascal / Free Pascal.', 'Ajuste o código conforme a sintaxe esperada e certifique-se de que todos os tipos e símbolos existem.', 'N', '') MATCHING (CODE);
