UPDATE OR INSERT INTO FPC_MESSAGES (CODE, SEVERITY, MESSAGE_PATTERN, DESCRIPTION_PTBR, PROBABLE_CAUSE, MANUAL_SOLUTION, CAN_AUTO_FIX, AUTO_FIX_STRATEGY) VALUES (4034, 'ERROR', 'Tipo interface esperado, mas obtido "$1"', 'The compiler expected to encounter an interface type name, but got something else.
The following code would produce this error:

Type
TMyStream = Class(TStream,Integer)', 'Erro sintático ou semântico que viola a especificação da linguagem Object Pascal / Free Pascal.', 'Ajuste o código conforme a sintaxe esperada e certifique-se de que todos os tipos e símbolos existem.', 'N', '') MATCHING (CODE);
UPDATE OR INSERT INTO FPC_MESSAGES (CODE, SEVERITY, MESSAGE_PATTERN, DESCRIPTION_PTBR, PROBABLE_CAUSE, MANUAL_SOLUTION, CAN_AUTO_FIX, AUTO_FIX_STRATEGY) VALUES (4035, 'HINT', 'Misturando expressões assinadas e ''longwords'' obtem-se um resultado de 64bits', 'If you divide (or calculate the modulus of) a signed expression by a longword (or vice versa),
or if you have overflow and/or range checking turned on and use an arithmetic
expression (+, -, *, div, mod) in which both signed numbers and longwords appear,
then everything has to be evaluated in 64-bit arithmetic which is slower than normal
32-bit arithmetic. You can avoid this by typecasting one operand so it
matches the result type of the other one.', 'O compilador detectou código redundante, parâmetros não utilizados ou oportunidades de otimização.', 'Revise a necessidade do elemento ou use supressão local se o padrão for intencional.', 'S', 'Ajustar visibilidade do método na classe derivada') MATCHING (CODE);
UPDATE OR INSERT INTO FPC_MESSAGES (CODE, SEVERITY, MESSAGE_PATTERN, DESCRIPTION_PTBR, PROBABLE_CAUSE, MANUAL_SOLUTION, CAN_AUTO_FIX, AUTO_FIX_STRATEGY) VALUES (4036, 'WARNING', 'Misturando expressões assinadas e cardinais pode causar um erro de verificação de faixa', 'If you use a binary operator (and, or, xor) and one of
the operands is a longword while the other one is a signed expression, then,
if range checking is turned on, you may get a range check error because in
such a case both operands are converted to longword before the operation is
carried out. You can avoid this by typecasting one operand so it
matches the result type of the other one.', 'Possível falha de lógica, incompatibilidade de tipos, obsolescência ou efeitos colaterais em tempo de execução.', 'Corrija a inconsistência apontada para evitar comportamentos inesperados no executável final.', 'N', '') MATCHING (CODE);
UPDATE OR INSERT INTO FPC_MESSAGES (CODE, SEVERITY, MESSAGE_PATTERN, DESCRIPTION_PTBR, PROBABLE_CAUSE, MANUAL_SOLUTION, CAN_AUTO_FIX, AUTO_FIX_STRATEGY) VALUES (4037, 'ERROR', 'Conversão de tipo tem tamanhos diferentes ($1 -> $2) na atribuição', 'Type casting to a type with a different size is not allowed when the variable is
used in an assignment.', 'Erro sintático ou semântico que viola a especificação da linguagem Object Pascal / Free Pascal.', 'Ajuste o código conforme a sintaxe esperada e certifique-se de que todos os tipos e símbolos existem.', 'N', '') MATCHING (CODE);
UPDATE OR INSERT INTO FPC_MESSAGES (CODE, SEVERITY, MESSAGE_PATTERN, DESCRIPTION_PTBR, PROBABLE_CAUSE, MANUAL_SOLUTION, CAN_AUTO_FIX, AUTO_FIX_STRATEGY) VALUES (4038, 'ERROR', 'Enumerações com atribuições não podem ser usadas como índice de matrizes', 'When you declared an enumeration type which has C-like
