Tenum = (a,b,e:=5);

you cannot use it as the index of an array.', 'Erro sintático ou semântico que viola a especificação da linguagem Object Pascal / Free Pascal.', 'Ajuste o código conforme a sintaxe esperada e certifique-se de que todos os tipos e símbolos existem.', 'N', '') MATCHING (CODE);
UPDATE OR INSERT INTO FPC_MESSAGES (CODE, SEVERITY, MESSAGE_PATTERN, DESCRIPTION_PTBR, PROBABLE_CAUSE, MANUAL_SOLUTION, CAN_AUTO_FIX, AUTO_FIX_STRATEGY) VALUES (4039, 'ERROR', 'Tipos Classe ou Objeto "$1" e "$2" não estão relacionados', 'There is a typecast from one class or object to another while the class/object
