UPDATE OR INSERT INTO FPC_MESSAGES (CODE, SEVERITY, MESSAGE_PATTERN, DESCRIPTION_PTBR, PROBABLE_CAUSE, MANUAL_SOLUTION, CAN_AUTO_FIX, AUTO_FIX_STRATEGY) VALUES (4044, 'WARNING', 'Comparison might be always false due to range of constant and expression', 'There is a comparison between a constant and an expression where the constant is out of the
