UPDATE OR INSERT INTO FPC_MESSAGES (CODE, SEVERITY, MESSAGE_PATTERN, DESCRIPTION_PTBR, PROBABLE_CAUSE, MANUAL_SOLUTION, CAN_AUTO_FIX, AUTO_FIX_STRATEGY) VALUES (4055, 'HINT', 'Conversão entre ordinais e ponteiros não é portável', 'If you typecast a pointer to a longint (or vice-versa), this code will not compile
on a machine using 64 bits addressing.', 'Conversão de tipo entre ponteiro e número ordinal de tamanho fixo (32-bit), incompatível com ponteiros de 64-bit.', 'Substitua o typecast Integer/Cardinal por PtrInt/PtrUInt para manter o código portável em 32 e 64 bits.', 'S', 'Substituir typecast por PtrInt/PtrUInt') MATCHING (CODE);
UPDATE OR INSERT INTO FPC_MESSAGES (CODE, SEVERITY, MESSAGE_PATTERN, DESCRIPTION_PTBR, PROBABLE_CAUSE, MANUAL_SOLUTION, CAN_AUTO_FIX, AUTO_FIX_STRATEGY) VALUES (4056, 'WARNING', 'Conversão entre ordinais e ponteiros não é portável', 'If you typecast a pointer to an ordinal type of a different size (or vice-versa), this can
cause problems. This is a warning to help in finding the 32-bit specific code where cardinal/longint is used
to typecast pointers to ordinals. A solution is to use the ptrint/ptruint types instead.', 'Conversão de tipo entre ponteiro e número ordinal de tamanho fixo (32-bit), incompatível com ponteiros de 64-bit.', 'Substitua o typecast Integer/Cardinal por PtrInt/PtrUInt para manter o código portável em 32 e 64 bits.', 'S', 'Substituir typecast por PtrInt/PtrUInt') MATCHING (CODE);
