UPDATE OR INSERT INTO FPC_MESSAGES (CODE, SEVERITY, MESSAGE_PATTERN, DESCRIPTION_PTBR, PROBABLE_CAUSE, MANUAL_SOLUTION, CAN_AUTO_FIX, AUTO_FIX_STRATEGY) VALUES (4059, 'WARNING', 'Convertendo constante valor real para ''double'' para variável argumento C, adicione conversão de tipo explícita para evitar isso.', 'In C, constant real values are double by default. For this reason, if you
pass a constant real value to a variable argument part of a C function, FPC
by default converts this constant to double as well. If you want to prevent
this from happening, add an explicit typecast around the constant.', 'Possível falha de lógica, incompatibilidade de tipos, obsolescência ou efeitos colaterais em tempo de execução.', 'Corrija a inconsistência apontada para evitar comportamentos inesperados no executável final.', 'N', '') MATCHING (CODE);
