UPDATE OR INSERT INTO FPC_MESSAGES (CODE, SEVERITY, MESSAGE_PATTERN, DESCRIPTION_PTBR, PROBABLE_CAUSE, MANUAL_SOLUTION, CAN_AUTO_FIX, AUTO_FIX_STRATEGY) VALUES (4082, 'WARNING', 'Convertendo ponteiros para inteiros assinados pode resultar em comparações de resultados incorretas e erros de faixa. Ao invés disso, use tipos não assinados.', 'The virtual address space on 32-bit machines runs from \$00000000 to \$ffffffff.
