UPDATE OR INSERT INTO FPC_MESSAGES (CODE, SEVERITY, MESSAGE_PATTERN, DESCRIPTION_PTBR, PROBABLE_CAUSE, MANUAL_SOLUTION, CAN_AUTO_FIX, AUTO_FIX_STRATEGY) VALUES (5080, 'ERROR', 'No complete definition of the formally declared class "$1" is in scope', 'Objecive-C and Java classes can be imported formally, without using the unit in which it is fully declared.
This enables making forward references to such classes and breaking circular dependencies amongst units.
However, as soon as you wish to actually do something with an entity of this class type (such as
access one of its fields, send a message to it, or use it to inherit from), the compiler requires the full definition
of the class to be in scope.', 'Erro sintático ou semântico que viola a especificação da linguagem Object Pascal / Free Pascal.', 'Ajuste o código conforme a sintaxe esperada e certifique-se de que todos os tipos e símbolos existem.', 'N', '') MATCHING (CODE);
UPDATE OR INSERT INTO FPC_MESSAGES (CODE, SEVERITY, MESSAGE_PATTERN, DESCRIPTION_PTBR, PROBABLE_CAUSE, MANUAL_SOLUTION, CAN_AUTO_FIX, AUTO_FIX_STRATEGY) VALUES (5081, 'ERROR', 'Gotos dentro de blocos de inicialização ou finalização de unidades não são permitidos', 'Gotos into initialization or finalization blockse of units are not allowed.', 'Erro sintático ou semântico que viola a especificação da linguagem Object Pascal / Free Pascal.', 'Ajuste o código conforme a sintaxe esperada e certifique-se de que todos os tipos e símbolos existem.', 'N', '') MATCHING (CODE);
UPDATE OR INSERT INTO FPC_MESSAGES (CODE, SEVERITY, MESSAGE_PATTERN, DESCRIPTION_PTBR, PROBABLE_CAUSE, MANUAL_SOLUTION, CAN_AUTO_FIX, AUTO_FIX_STRATEGY) VALUES (5082, 'ERROR', 'Nome externo inválido "$1" para classe formal "$2"', 'Diagnóstico ERROR código 5082 emitido pelo compilador Free Pascal: Nome externo inválido "$1" para classe formal "$2"', 'Erro sintático ou semântico que viola a especificação da linguagem Object Pascal / Free Pascal.', 'Ajuste o código conforme a sintaxe esperada e certifique-se de que todos os tipos e símbolos existem.', 'N', '') MATCHING (CODE);
UPDATE OR INSERT INTO FPC_MESSAGES (CODE, SEVERITY, MESSAGE_PATTERN, DESCRIPTION_PTBR, PROBABLE_CAUSE, MANUAL_SOLUTION, CAN_AUTO_FIX, AUTO_FIX_STRATEGY) VALUES (5083, 'ERROR', 'Complete a definição de classe com nome externo "$1" aqui', 'When a class is declared using a formal external definition, the actual external
definition (if any) must specify the same external name as the formal definition
(since both definitions refer to the same actual class type).', 'Erro sintático ou semântico que viola a especificação da linguagem Object Pascal / Free Pascal.', 'Ajuste o código conforme a sintaxe esperada e certifique-se de que todos os tipos e símbolos existem.', 'N', '') MATCHING (CODE);
UPDATE OR INSERT INTO FPC_MESSAGES (CODE, SEVERITY, MESSAGE_PATTERN, DESCRIPTION_PTBR, PROBABLE_CAUSE, MANUAL_SOLUTION, CAN_AUTO_FIX, AUTO_FIX_STRATEGY) VALUES (5084, 'WARNING', 'Possível conflito em biblioteca: símbolo "$1" da biblioteca "$2" também encontrado na biblioteca "$3"', 'Some OS do not have library specific namespaces, for those
OS, the function declared as "external ''libname'' name ''funcname''",
the ''libname'' part is only a hint, funcname might also be loaded
by another library. This warning appears if ''funcname'' is used twice
with two different library names.

This section lists all messages that can be displayed if the code
generator encounters an error condition.', 'Possível falha de lógica, incompatibilidade de tipos, obsolescência ou efeitos colaterais em tempo de execução.', 'Corrija a inconsistência apontada para evitar comportamentos inesperados no executável final.', 'N', '') MATCHING (CODE);
UPDATE OR INSERT INTO FPC_MESSAGES (CODE, SEVERITY, MESSAGE_PATTERN, DESCRIPTION_PTBR, PROBABLE_CAUSE, MANUAL_SOLUTION, CAN_AUTO_FIX, AUTO_FIX_STRATEGY) VALUES (5085, 'ERROR', 'Cannot add implicit constructor ''Create'' because identifier already used by "$1"', 'Java does not automatically add inherited constructors to child classes, so that they can be hidden.
However, if a class does not explicitly declare at least one constructor, the compiler is
required to add a public, parameterless constructor. In Java, constructors are nameless,
but in FPC they are all called ``Create''''. Therefore, if you do not add a constructor to
a Java class and furthermore use the ``Create'''' identifier for another entity (e.g., a field,
or a parameterless method), the compiler cannot satisfy this requirement.', 'Erro sintático ou semântico que viola a especificação da linguagem Object Pascal / Free Pascal.', 'Ajuste o código conforme a sintaxe esperada e certifique-se de que todos os tipos e símbolos existem.', 'N', '') MATCHING (CODE);
UPDATE OR INSERT INTO FPC_MESSAGES (CODE, SEVERITY, MESSAGE_PATTERN, DESCRIPTION_PTBR, PROBABLE_CAUSE, MANUAL_SOLUTION, CAN_AUTO_FIX, AUTO_FIX_STRATEGY) VALUES (5086, 'ERROR', 'Cannot generate default constructor for class, because parent has no parameterless constructor', 'Java does not automatically add inherited constructors to child classes, so that they can be hidden.
However, if a class does not explicitly declare at least one constructor, the compiler is
required to add a public, parameterless constructor. This compiler must then call
the parameterless constructor from the parent class inside this added constructor.
This is however impossible if the parent class does not declare such a constructor.
In this case you must add a valid constructor yourself.', 'Erro sintático ou semântico que viola a especificação da linguagem Object Pascal / Free Pascal.', 'Ajuste o código conforme a sintaxe esperada e certifique-se de que todos os tipos e símbolos existem.', 'N', '') MATCHING (CODE);
