1:
...', 'Erro sintático ou semântico que viola a especificação da linguagem Object Pascal / Free Pascal.', 'Ajuste o código conforme a sintaxe esperada e certifique-se de que todos os tipos e símbolos existem.', 'N', '') MATCHING (CODE);
UPDATE OR INSERT INTO FPC_MESSAGES (CODE, SEVERITY, MESSAGE_PATTERN, DESCRIPTION_PTBR, PROBABLE_CAUSE, MANUAL_SOLUTION, CAN_AUTO_FIX, AUTO_FIX_STRATEGY) VALUES (6040, 'ERROR', 'Instruções de controle de fluxo não são permitidos em um bloco ''finally''', 'It isn''t allowed to use the control flow statements ''break'',
''continue'' and ''exit''
inside a finally statement. The following example shows the problem:

...
