UPDATE OR INSERT INTO FPC_MESSAGES (CODE, SEVERITY, MESSAGE_PATTERN, DESCRIPTION_PTBR, PROBABLE_CAUSE, MANUAL_SOLUTION, CAN_AUTO_FIX, AUTO_FIX_STRATEGY) VALUES (6046, 'FATAL', '''Compilerproc'' desconhecido "$1". Verifique se você usa a biblioteca de tempo de execução correta', 'The compiler expects that the runtime library contains certain subroutines. If you see this error
and you didn''t change the runtime library code, it''s very likely that the runtime library
