UPDATE OR INSERT INTO FPC_MESSAGES (CODE, SEVERITY, MESSAGE_PATTERN, DESCRIPTION_PTBR, PROBABLE_CAUSE, MANUAL_SOLUTION, CAN_AUTO_FIX, AUTO_FIX_STRATEGY) VALUES (6047, 'FATAL', 'Impossível encontrar tipo sistema "$1". Verifique se você usa a biblioteca de tempo de execução correta', 'The compiler expects that the runtime library contains certain type definitions. If you see this error
