UPDATE OR INSERT INTO FPC_MESSAGES (CODE, SEVERITY, MESSAGE_PATTERN, DESCRIPTION_PTBR, PROBABLE_CAUSE, MANUAL_SOLUTION, CAN_AUTO_FIX, AUTO_FIX_STRATEGY) VALUES (6049, 'ERROR', 'Rótulo ''Goto'' "$1" não definido ou eliminado pela otimização', 'The label used in the goto definition is not defined or optimized away by the
